custom_css:
body.page-id-390 .page-header { display: none; }
/* The theme gives sibling parent containers a 4rem bottom margin; this section spaces itself. */
body.page-id-390 .e-con.e-parent, body .aicsu-rai .e-con { margin-bottom: 0 !important; }
.aicsu-rai { --kit-widget-spacing: 0px; --widgets-spacing: 0px; }
/* Lockup matches the colostate.edu header: Poppins 600 lead word, Bodoni Moda italic 400 highlighted word, same font size. */
.aicsu-rai .aicsu-rai-h2 .elementor-heading-title { margin: 0; font-family: Poppins, sans-serif; font-style: normal; font-weight: 600; font-size: clamp(2.5rem, 4.5vw, 3.75rem); line-height: 1.25; color: #1E4D2B; }
.aicsu-rai .aicsu-rai-h2 .aicsu-rai-hl { display: inline-block; padding: 0 .235em .094em; background: #7E5475; color: #FFFFFF; font-family: "Bodoni Moda", Georgia, serif; font-style: italic; font-weight: 400; font-size: 1em !important; line-height: inherit; }
.aicsu-rai .aicsu-rai-intro p { margin: 0; max-width: 760px; font-size: 1.25rem; line-height: 1.55; color: #1E4D2B !important; }
.aicsu-rai .aicsu-rai-intro a { color: #1E4D2B; font-weight: 600; text-decoration: underline; }
/* Two across with the 20px gap, so the full-width last card lines up with the grid edge. */
.aicsu-rai .aicsu-card { width: calc(50% - 10px) !important; }
.aicsu-rai .aicsu-card-wide { width: 100% !important; }
@media (max-width: 767px) { .aicsu-rai .aicsu-card { width: 100% !important; } }
.aicsu-rai .aicsu-card-topic p { margin: 0; font-size: .8125rem; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: #59595B !important; }
.aicsu-rai .aicsu-card-q .elementor-heading-title { margin: 0; font-size: clamp(1.25rem, 1.8vw, 1.6rem); font-weight: 600; line-height: 1.3; color: #1E4D2B; }
.aicsu-rai .aicsu-card-links { margin-top: 8px; }
.aicsu-rai .aicsu-card-links ul { list-style: none; margin: 0; padding: 0; border-top: 1px solid #CCCCCC; }
.aicsu-rai .aicsu-card-links li { padding: 14px 0; border-bottom: 1px solid #CCCCCC; line-height: 1.4; }
.aicsu-rai .aicsu-card-links li:last-child { border-bottom: 0; padding-bottom: 0; }
.aicsu-rai .aicsu-card-soon { margin-top: auto; padding-top: 14px; border-top: 1px solid #CCCCCC; }
.aicsu-rai .aicsu-card-soon p { margin: 0; font-weight: 600; color: #59595B !important; }
.aicsu-rai .aicsu-card-links a { font-weight: 600; color: #B8432F; text-decoration: underline; }
.aicsu-rai .aicsu-card-links a:hover { color: #1E4D2B; }
.aicsu-rai .aicsu-card-links .src { display: block; margin-top: 2px; font-size: .9375rem; color: #59595B; }
